<?php require __DIR__.'/bootstrap.php';require_admin();$items=read_json('subscribers.json',[]);if(isset($_GET['export'])){header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="bakery-bake-subscribers.csv"');$out=fopen('php://output','w');fputcsv($out,['Email','Subscribed at','Status','Consent']);foreach($items as $s)fputcsv($out,[$s['email'],$s['created_at'],$s['status'],$s['consent']?'yes':'no']);fclose($out);exit;}if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$id=(string)($_POST['id']??'');foreach($items as &$s)if($s['id']===$id)$s['status']='unsubscribed';unset($s);write_json('subscribers.json',$items);redirect('admin-subscribers.php');}site_header('Newsletter subscribers'); ?>
<div class="admin-shell"><h1 style="font:42px 'Playfair Display',serif">Newsletter subscribers</h1><nav class="admin-nav"><a href="admin.php">Overview</a><a href="admin-products.php">Products</a><a href="admin-orders.php">Orders</a><a href="admin-settings.php">Settings</a><a href="admin-gallery.php">Gallery</a><a href="admin-notifications.php">Notifications</a><a href="admin-subscribers.php">Newsletter</a><a href="admin-requests.php">Custom requests</a><a href="admin-logout.php">Sign out</a></nav><p><a class="button" href="?export=1">Export CSV</a></p><div class="card-panel table-wrap"><table class="data-table"><thead><tr><th>Email</th><th>Subscribed</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($items as $s): ?><tr><td><?= e($s['email']) ?></td><td><?= e($s['created_at']) ?></td><td><?= e($s['status']) ?></td><td><?php if($s['status']==='subscribed'): ?><form method="post"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= e($s['id']) ?>"><button class="text-link" type="submit">Unsubscribe</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><div class="notice">Newsletter sending is not an email campaign platform by itself. Configure an appropriate email marketing provider before sending bulk campaigns.</div></div><?php site_footer(); ?>
